// Applies the SQL migrations in apps/api/drizzle (generated by `pnpm db:generate`) using drizzle's
// journal table, so production databases are upgraded incrementally. Dev databases use `pnpm db:push`
// instead; never mix the two on one database (see docs/OPERATIONS.md).
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import path from 'node:path';
import { API_ROOT, loadDotenv } from '../lib/env.js';
import { createDb, type Db } from './client.js';

export const MIGRATIONS_DIR = path.join(API_ROOT, 'drizzle');

export async function runMigrations(db: Db): Promise<void> {
  await migrate(db, { migrationsFolder: MIGRATIONS_DIR });
}

const isEntrypoint = process.argv[1] !== undefined && path.resolve(process.argv[1]).includes(path.join('db', 'migrate'));
if (isEntrypoint) {
  loadDotenv();
  const url = process.env.DATABASE_URL ?? 'postgres://localhost:5432/vantra';
  const handle = createDb(url, { max: 1 });
  try {
    await runMigrations(handle.db);
    console.log(`migrations applied from ${MIGRATIONS_DIR}`);
  } finally {
    await handle.close();
  }
}
